define({"topics":[{"title":"Applying LOTO - Global Operator Cabinet (GOC) and Operator Workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e1352","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and Operator Workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e1454","topics":[]}]});